package edu.pe.cibertec.saibm.usuario.infrastructure.messaging; import org.springframework.amqp.core.*; import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter; import org.springframework.context.annotation.*; import com.fasterxml.jackson.databind.ObjectMapper; @Configuration public class UserRabbitConfig {public static final String EXCHANGE="saibm.user.v1",DLQ="user-dlq";@Bean Jackson2JsonMessageConverter userConverter(ObjectMapper m){return new Jackson2JsonMessageConverter(m);}@Bean TopicExchange userExchange(){return new TopicExchange(EXCHANGE,true,false);}@Bean Queue userEvents(){return QueueBuilder.durable("user-events").deadLetterExchange(EXCHANGE).deadLetterRoutingKey(DLQ).build();}@Bean Binding userEventsBinding(){return BindingBuilder.bind(userEvents()).to(userExchange()).with("#");}@Bean Queue userDlq(){return QueueBuilder.durable(DLQ).build();}@Bean Binding userDlqBinding(){return BindingBuilder.bind(userDlq()).to(userExchange()).with(DLQ);}}
